//! The Rust half of the key-binding and gate vectors
//! (packages/protocol/test-vectors/pq-binding/vectors.json, generated by
//! tools/pq-binding-vectors.ts). Every valid binding must verify and re-sign
//! byte for byte; every refusal must carry the same code as TypeScript.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]

use flagship_crypto::HybridSigningKey;
use flagship_crypto::trust::{
    BindingWire, Envelope, Expectation, PolicyState, Profile, Role, Rollout, TAG_PQ_KEY_BINDING,
    TrustError, VerifiedBinding, canonical_binding, hex, message_purpose, verify_binding,
    verify_critical_signature,
};
use flagship_protocol::parse::parse_lower_hex;
use serde_json::Value;
use std::path::PathBuf;

fn vectors() -> Value {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../packages/protocol/test-vectors/pq-binding/vectors.json");
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v[k].as_str().unwrap_or("")
}

const WIRE_KEYS: [&str; 7] = [
    "ed25519PubHex",
    "issuedAt",
    "mldsaPubHex",
    "role",
    "signature",
    "subjectId",
    "v",
];

/// The JSON-level checks TypeScript makes before the typed ones: exact keys,
/// `v: 1`, string fields, an integer issuedAt.
fn wire(v: &Value) -> Result<BindingWire<'_>, TrustError> {
    let o = v.as_object().ok_or(TrustError::BindingMalformed)?;
    let mut keys: Vec<&str> = o.keys().map(String::as_str).collect();
    keys.sort_unstable();
    if keys != WIRE_KEYS || v["v"].as_u64() != Some(1) {
        return Err(TrustError::BindingMalformed);
    }
    for k in [
        "signature",
        "ed25519PubHex",
        "mldsaPubHex",
        "role",
        "subjectId",
    ] {
        if !v[k].is_string() {
            return Err(TrustError::BindingMalformed);
        }
    }
    Ok(BindingWire {
        role: s(v, "role"),
        subject_id: s(v, "subjectId"),
        ed25519_pub_hex: s(v, "ed25519PubHex"),
        mldsa_pub_hex: s(v, "mldsaPubHex"),
        issued_at: u64::MAX,
        signature_hex: s(v, "signature"),
    })
}

fn verify(v: &Value, e: &Value) -> Result<VerifiedBinding, TrustError> {
    let mut w = wire(v)?;
    // A non-integer issuedAt is refused at the same point as TypeScript: after
    // the signature and key hex, before role and subject.
    parse_lower_hex(w.signature_hex, 0, 1 << 16).map_err(|_| TrustError::BindingMalformed)?;
    parse_lower_hex(w.ed25519_pub_hex, 32, 32).map_err(|_| TrustError::BindingMalformed)?;
    parse_lower_hex(w.mldsa_pub_hex, 1952, 1952).map_err(|_| TrustError::BindingMalformed)?;
    w.issued_at = v["issuedAt"].as_u64().ok_or(TrustError::BindingMalformed)?;
    let role = Role::parse(s(e, "role")).unwrap();
    let pinned = e["mldsaPubHex"].as_str();
    verify_binding(
        &w,
        &Expectation {
            role,
            subject_id: s(e, "subjectId"),
            ed25519_pub_hex: s(e, "ed25519PubHex"),
            mldsa_pub_hex: pinned,
            now: e["now"].as_u64().unwrap(),
            min_issued_at: e["minIssuedAt"].as_u64(),
        },
    )
}

fn signer(v: &Value, name: &str) -> HybridSigningKey {
    let sv = v["signers"]
        .as_array()
        .unwrap()
        .iter()
        .find(|x| x["name"] == name)
        .unwrap();
    let ed: [u8; 32] = parse_lower_hex(s(sv, "edSeedHex"), 32, 32)
        .unwrap()
        .try_into()
        .unwrap();
    let ml: [u8; 32] = parse_lower_hex(s(sv, "mldsaSeedHex"), 32, 32)
        .unwrap()
        .try_into()
        .unwrap();
    HybridSigningKey::from_seeds(&ed, &ml).unwrap()
}

#[test]
fn valid_bindings_verify_and_resign_byte_for_byte() {
    let v = vectors();
    let signers: Vec<(&str, &str)> = v["signers"]
        .as_array()
        .unwrap()
        .iter()
        .map(|x| (s(x, "name"), s(x, "ed25519PubHex")))
        .collect();
    for c in v["bindings"]["valid"].as_array().unwrap() {
        let w = &c["wire"];
        let stmt = canonical_binding(
            s(w, "role"),
            s(w, "subjectId"),
            s(w, "ed25519PubHex"),
            s(w, "mldsaPubHex"),
            w["issuedAt"].as_u64().unwrap(),
        )
        .unwrap();
        assert_eq!(hex(&stmt), s(c, "statementHex"), "{}", s(c, "name"));
        let b = verify(w, &c["expect"]).unwrap_or_else(|e| panic!("{}: {e}", s(c, "name")));
        assert_eq!(b.subject_id(), s(w, "subjectId"));
        let name = signers
            .iter()
            .find(|(_, ed)| *ed == s(w, "ed25519PubHex"))
            .unwrap()
            .0;
        let sig = signer(&v, name)
            .sign_deterministic(TAG_PQ_KEY_BINDING, &stmt)
            .unwrap();
        assert_eq!(hex(&sig), s(w, "signature"), "{}", s(c, "name"));
        // Production signing is hedged: different bytes, same verdict.
        let hedged = signer(&v, name).sign(TAG_PQ_KEY_BINDING, &stmt).unwrap();
        b.hybrid_key()
            .verify(TAG_PQ_KEY_BINDING, &stmt, &hedged)
            .unwrap();
    }
}

#[test]
fn invalid_bindings_refuse_with_the_same_code() {
    let v = vectors();
    for c in v["bindings"]["invalid"].as_array().unwrap() {
        let got = verify(&c["wire"], &c["expect"]).map(|_| ()).err();
        assert_eq!(
            got.map(TrustError::code),
            Some(s(c, "code")),
            "{}",
            s(c, "name")
        );
    }
}

fn policy(p: &Value) -> PolicyState {
    PolicyState {
        profile: match s(p, "profile") {
            "strict" => Profile::Strict,
            _ => Profile::Compatibility,
        },
        rollout: match s(p, "rollout") {
            "legacy" => Rollout::Legacy,
            "capable" => Rollout::Capable,
            "prepared" => Rollout::Prepared,
            "enforced" => Rollout::Enforced,
            _ => Rollout::Retired,
        },
    }
}

#[test]
fn gate_cases() {
    let v = vectors();
    for c in v["gate"].as_array().unwrap() {
        let binding = c["binding"].as_str().map(|name| {
            let vb = v["bindings"]["valid"]
                .as_array()
                .unwrap()
                .iter()
                .find(|x| x["name"] == name)
                .unwrap();
            verify(&vb["wire"], &vb["expect"]).unwrap()
        });
        let msg = parse_lower_hex(s(c, "messageHex"), 0, 1 << 20).unwrap();
        let got = verify_critical_signature(
            &msg,
            s(c, "expectedPurpose"),
            Envelope {
                suite: s(&c["envelope"], "suite"),
                signature_hex: s(&c["envelope"], "signature"),
            },
            s(c, "signerEd25519PubHex"),
            binding.as_ref(),
            &policy(&c["policy"]),
        );
        let e = &c["expect"];
        if e["ok"].as_bool().unwrap() {
            let verdict = got.unwrap_or_else(|err| panic!("{}: {err}", s(c, "name")));
            assert_eq!(verdict.suite.as_str(), s(e, "suite"), "{}", s(c, "name"));
            assert_eq!(verdict.strict, e["strict"].as_bool().unwrap());
        } else {
            assert_eq!(
                got.err().map(TrustError::code),
                Some(s(e, "code")),
                "{}",
                s(c, "name")
            );
        }
    }
}

#[test]
fn purpose_of_message() {
    assert_eq!(message_purpose(b"flagship/x/v1|a|b"), "flagship/x/v1");
    assert_eq!(message_purpose(b"|a"), "");
    assert_eq!(message_purpose(b"no-bar"), "");
    assert_eq!(message_purpose(&[0xff, b'|']), "");
}
